/** Optional read-only MCP tools; semantic work delegates to the existing analysis services. */
class WicketLensMcpToolset : McpToolset {
    // Expose the bounded read-only tools with the host's default experimental filter off.
    override fun isExperimental() = false

    @Suppress("FunctionName")
    @McpTool(title = "WicketLens MCP connectivity probe")
    @McpDescription("Verify that WicketLens is reachable through the JetBrains MCP server. Returns static, versioned JSON; does not read or modify project files and does not perform semantic analysis.")
    @McpToolHints(readOnlyHint = McpToolHintValue.TRUE, destructiveHint = McpToolHintValue.FALSE,
        idempotentHint = McpToolHintValue.TRUE, openWorldHint = McpToolHintValue.FALSE)
    suspend fun wicketlens_mcp_probe(): String =
        """{"schemaVersion":1,"plugin":"WicketLens","tool":"wicketlens_mcp_probe","phase":1,"status":"ok","semanticAnalysis":false}"""

    @Suppress("FunctionName")
    @McpTool(title = "Get Wicket page structure")
    @McpDescription("Analyze a source Wicket WebPage, Panel, or FormComponentPanel in the host-selected project. Returns MCP envelope schema 1 containing analysis schema 1, with component hierarchy, Java/markup locations, findings, and uncertainty. Bounded if/else and ternary merging confirms common evaluated ID/type/parent paths, including computed IDs, and retains conditional alternatives with conditional=true, UNRESOLVED_BRANCH findings, branchMerged and all javaLocations/idLocations. Computed IDs include typed idOrigins (LITERAL/COMPUTED); idRenameSafe=false protects calculation fragments. Stable boolean parameters, local aliases, negation, reviewed compound &&/|| predicates, primitive boolean ==/!= and eager &/|/^ operators reuse input path facts. Eager operands are all audited before proof; stable integral inputs compared with known constants share repeated, reversed, complementary and adjacent-threshold facts. Primitive bounds are respected without inferring runtime numbers. Per-input interval bounds and excluded equality values now combine different thresholds to avoid impossible setup paths. Ranges never supply computed IDs or runtime numbers; relations between distinct unknown inputs, symbolic arithmetic and opaque calls remain conservative. Queue placement is checked on each feasible setup path; conditional queues remain unresolved and path membership is not exported. Common repeater item bindings remain INFERRED templates across branches; optional item structure stays unresolved, logical items have no runtime ID, and row counts remain unknown. Runtime branch and model values remain unknown. Audited source-layout construction also supports decorated components, constructor delegation, initialization fields and concrete-page hooks. Transparent markup uses ordinary-child precedence and parent fallback; simple localization markup preserves scope. Fragment definitions project into proved root-provider instances with separate attachment IDs and source locations. Optional fragmentUses and component fragment metadata distinguish definition lookup from instantiation; uncalled factories gain no component path. Reused definitions have separate contexts and guarded editing. Bounded source factories follow lambda/method-reference ID arguments and captures, compose proved source-owned Panel markup, and represent reviewed iterator/newChildId populations as inferred templates. sourceSetupExpanded and ownedMarkupPath identify composed component scopes; markupProviderNodeId separates provider markup instances. No concrete runtime row IDs, counts, data values or post-event tree are inferred. With includeNavigationContexts, a matched standard AjaxLink handler can also expose a separate EVENT_TEMPLATE with lifecycle.kind=SOURCE_DECLARED_EVENT_CONTENT and directContent provenance for fresh source Fragment content supplied to a guarded owned slot. The target path uses PAGE_DECLARED_ATTACHMENT; triggerComponentPath and triggerPopulationContextId retain a separate SYMBOLIC_ITEMS row context with unknown runtime IDs/counts. Handler/configuration execution is not_evaluated; models, visibility, validation, open/close state, other event effects and later tree state stay unknown. These five inferred bindings in the DialogPage case do not alter its initial placeholder, validation or primary selectors. Native navigation shares the graph and grants no paired-rename authority. With includeNavigationContexts, bounded registered source constructor references can expose separate EVENT_TEMPLATE contexts for source-declared replacement sites. lifecycle metadata records factory/invocation/replacement locations and the conditional host path; their MATCHED bindings are INFERRED templates with unknown runtime presence. Registered source step factories can also expose separate SELECTION_TEMPLATE contexts at the shared body slot. Reviewed source setters that immediately invoke a unary fragment factory and replace their own slot can expose FACTORY_TEMPLATE contexts (SOURCE_DECLARED_CONTENT_FACTORY / REGISTRATION_TEMPLATE). Their nested form declarations, registration/ID/configuration/callback locations reuse native graphs. Source invocation is immediate; factory and callbacks are not evaluated, configuration effects/model values/visibility/later state stay unknown. Primary selectors and default responses are unchanged. Reviewed null-guarded source DataTable toolbar caches and immediate content factories can expose TABLE_TOOLBAR_TEMPLATE contexts with toolbarTemplate provenance and TOOLBAR_RELATIVE cell/content/owned-child bindings. Framework-assigned toolbar IDs, row count, visibility, colspan, models and later state remain unknown; factories/callbacks are not evaluated. Source cache/table/cell ownership, constructor ID forwarding and source resources are checked; no full page-to-toolbar runtime path or editing authority is supplied. lifecycle.kind=SOURCE_DECLARED_STEP_SELECTION and lifecycle.selection record registrationIndex/count, optional title, fragment definitionId, opaque index location and optional initialization call location. Source order is not the current runtime index. Each step remains separate with INFERRED template bindings; constructor/configuration effects, form internals and validation outcomes remain unknown. Source NestedTree/TableTree node factories can expose separate TREE_TEMPLATE contexts. treeTemplate.pathScope=NODE_RELATIVE means paths start at one logical node; hostComponentPath is a separate source attachment, not a usable runtime prefix. Explicit nullness conditions are template preconditions, never current callback state. Runtime ancestry/IDs/count, expansion and selection remain unknown. Optional possibleComponentTypes records same-ID constructor alternatives without selecting a concrete type. Node/content markup and source conditions reuse the shared semantic graph and matcher. Abstract source base pages with one valid open wicket:child slot can expose a primary baseLayoutTemplate when every reviewed constructor entry has the same audited shell. These MATCHED bindings are INFERRED under DECLARED_IMPLEMENTATIONS and BASE_RELATIVE paths; runtime constructor selection, subclasses, extension contents and model values stay unknown. Constructor signatures/locations and extension slots preserve source provenance. Unfilled slots remain local boundaries, not complete runtime markup. Distinct or unsafe constructor setups stay unresolved. Concrete page analysis remains unchanged. A bounded fallback can expose initialContentSetup with kind SOURCE_DECLARED_INITIAL_CONTENT and phase INITIAL_DECLARATIONS for source-owned dialog/content setters. It follows private-final form/slot declarations, a throwing content-ID guard, inherited fluent setters and initial Fragment instances. Every binding in this fallback is INFERRED and protected from paired rename. Constructor/configuration effects, model values, validation, visibility and later open/close/replacement state remain unknown; constructors, configurations and event callbacks are not executed. Metadata records host/slot/content node IDs, selected constructor/setter/placement sources and deferred callback locations. Source Ajax hooks with empty base implementations stay deferred; direct setup calls into event hooks, structural configuration, ambiguous ancestry, wrong IDs and competing placements withhold the declaration graph. Initial selectors describe these source declarations, never current runtime dialog state. Source ListView item populations can add primary populationTemplates with separate item-predicate preconditions, shared helper/factory declarations and nested symbolic items. A primitive boolean model predicate selects a source path; requiredResult is a precondition for one logical row, never current model state or a global page choice. Separate leaf/group rows can coexist at runtime. runtimeItemIds, rowCount, modelValues, predicateResults, authorization, visibility and runtimeSubclass stay unknown; configuration/callback execution is not_evaluated. Contexts retain exact item findings and required ancestors, with per-branch empty hidden placeholder bodies projected from source declarations. Template-covered primary markup stays UNRESOLVED_BRANCH rather than acquiring an unconditional binding. Native references and text reports share these graphs; initial selectors still cannot select template-only children. Optional navigation discovery can expose the same graphs as REPEATER_TEMPLATE contexts with 4/7 item bindings in the Oat sidebar case. Reviewed source static ListView factories can bridge a direct item/data lambda through populateItem. Optional registeredListPopulation and populationTemplate.registration retain factory, bridge, callback, item-wrapper and behavior locations. Source forwarding and behavior-only default newItem decoration are checked; other custom item factories, callback escapes and captured component mutations remain unresolved. Hosts and item children are INFERRED and protected from paired rename. Item callback execution is not_evaluated and behavior effects remain unknown. Population discovery is bounded to 20000 steps, 96 sources, 4 contexts, 128 nodes, 12 source/statement levels, 3 nested repeaters and two branching decisions. Exhaustion publishes no partial population graphs, marks populationDiscoveryComplete=false and truncated for structure/validation/context; unsupported patterns retain diagnostics. Source lazy composite form inputs can expose separate FORM_TEMPLATE contexts. formTemplate.pathScope=WRAPPER_RELATIVE and inputComponentPath describe declared input/child paths inside a source wrapper, not an enclosing page path or current runtime hierarchy. Private null-guarded caches, fresh source factories/helpers and private-final constructor fields reuse shared declarations, identity and transparent/owned markup matching. Registered custom input constructor references can add formTemplate.registration source provenance for wrapper construction, constructor reference/target and private final factory storage. Separate registrations retain separate wrapper-relative templates without establishing a concrete page attachment; their context className/moduleName identify the registering source owner, while wrapperClassName identifies the graph root type. Conversion, required-check and validator hooks are source locations with execution=not_evaluated. Runtime presence, conversion/validation results, required state and model values remain unknown. Initial analysis stays unchanged. Lifecycle, tree and form bindings include ancestors and children inline; ordinary component-context and validation requests continue to select the initial graph. This does not execute New/Edit, save/delete, models or validation. Unsafe captured mutations, factory escapes and unsupported lifecycle/factory patterns stay unresolved. Bounded owned form summaries can confirm wrapper attachments through private lazy inputs and privately forwarded constructor references; internal inputs, conversion and validation remain unexpanded. Component-owned and repeater contents, other providers and custom fragment strategies can remain unresolved even when their attachment matches. Named member source markup owners use binary-name companions such as Outer\$Fields.html; className uses dots. With includeNavigationContexts, ordinary AjaxButton/source-subclass onSubmit and onError overrides can also expose SUBMISSION_TEMPLATE entries with submissionTemplate.kind=SOURCE_DECLARED_FORM_CALLBACK, pathScope=OWN_COMPANION_DECLARATIONS and formCallback source attachment/constructor/form-association provenance. SOURCE_ON_SUBMIT_ROUTE and SOURCE_ON_ERROR_ROUTE identify source hooks, not validation outcomes. bridgeLocation and dispatchLocation are null for direct framework callbacks. Source-declared additions may be described while the initial hierarchy stays unresolved; initialization, inherited placement, runtime presence and business/model outcomes remain unknown. Feedback/Ajax effect targets use SOURCE_DECLARED_ADDITIONS attachment phase. Default views and selectors stay initial; callbacks are not evaluated. Optional includeNavigationContexts also supplies separate CONFIRMATION_TEMPLATE stored-consumer declarations when source ask/slot/capture/clear/guard/accept and standard submit route checks succeed. submissionTemplate.confirmation retains source registration, cleanup and one private data-helper call. Initiating dispatch, current slot identity/presence, cleanup reachability, data/equals effects and business outcomes stay unknown; no callback is executed. Optional confirmation.selectionClears records guarded source model-collection clear helpers and same-owner Ajax refresh declarations. Column presence/dispatch, IModel.getObject implementations, collection identity/mutability, clear/refresh outcomes and later selection remain unknown; no helper or model is evaluated.  Separate ACTION_TEMPLATE contexts describe source constructor BiConsumer arguments with one reviewed private List.replaceAll loop and canonical record enum-component substitution. actionTemplate retains registration, loop, equality, record-transform and component-argument source locations plus shared feedback/Ajax/selection-helper declarations. Registration/storage, UI dispatch, visibility, rows, equality/enum effects and mutation/business outcomes stay unknown. No callback, helper, predicate or record constructor is executed; no runtime trigger ID or form association is reconstructed. Initial attachment declarations can also retain source-proved callback storage on a fresh constructor-local registrar whose complete method only assigns its private callback slot and returns itself. Optional storedActionRegistrations records allocation, registration, method, slot and callback locations. A registrar can have up to 64 standalone or fluent-chained registration links after all of its local uses pass the same storage-only audit and each link returns this; aliases, eager calls or escapes withhold the entire group. Entries sharing allocation and slot locations describe source sites, not concurrently active callbacks. Chain and local-initializer registrationLocation values point to distinct method-name tokens and action contexts reuse those exact locations. A direct new allocation may root a named constructor-local initializer chain; its links and every later local use share the same complete audit and 64-site limit. Bare allocations, aliases, fields and arbitrary factories are not granted local identity. All such attachment bindings are INFERRED with no rename authority; later active registration, dispatch, visibility, tree state and business outcomes remain unknown. Existing default views remain unchanged. Optional includeNavigationContexts also supplies separate SUBMISSION_TEMPLATE source dialog submission declarations: reviewed owned AjaxButton.onSubmit-to-hook bridge, inferred trigger/ancestor bindings, feedback receivers, stable declared Ajax targets and guarded fresh content placement. submissionTemplate metadata retains source bridge/dispatch/hook/effect locations. Callback execution is not_evaluated; default form processing, validation, models, feedback/business outcomes, runtime reachability and later tree/open/close state remain unknown. SOURCE_ON_SUBMIT_ROUTE does not imply successful validation. Initial selectors/default responses stay unchanged; submission graphs grant no editing authority. Optional includeNavigationContexts adds own/caller/inherited, replacement-site event, registered-step selection, node-relative tree and lazy composite form contexts through indexed source references and inheritors, plus one bounded configurable-host registration hop, with exact shared binding projections. Unproved indexed uses remain CANDIDATE entries with no invented scope or binding. Discovery bounds are 256 references, 256 inheritor visits, 16 caller candidates and 256 bindings; probing stops after the 512-source threshold. discoveryComplete and diagnostics expose incomplete discovery; truncated then refers to context discovery, while the primary graph remains intact. Default false retains the existing response. Bounded ID origin-use auditing reuses idRenameSafe (false is explicit; true can be omitted). This is origin eligibility only: native rename also checks current markup, sharing, variants, inheritors and writability, and all MCP tools remain read-only. Contexts do not enumerate arbitrary helper call chains or runtime uses and do not enable edits. Uses conventional default markup, not an editor-selected locale/style variant. Requires projectPath supplied by the host. Waits up to 30 seconds for smart/committed PSI and analysis, checks freshness after serialization, and rejects responses over 512 KiB rather than truncating. Does not save files, change sidebar/clipboard state, or provide runtime/model-value guarantees. Reinvoke after edits. Tool errors contain versioned JSON codes. Finite counted root-constructor loops can be audited for isolated data initialization using primitive/immutable and canonical source record data in fresh ArrayList storage. Loop execution, model values and collection contents are not evaluated. Unsupported loop effects or later setup failures withhold the full expansion and retain the exact blocking source diagnostic. Source dialog wrappers may declare one private-final constructor-owned message in an inherited guarded content slot. Existing initialContentSetup records its constructor placement; bindings are inferred and model/visibility/action effects remain unknown. No constructor or callback is executed. Reviewed source AbstractColumn and LambdaColumn wrappers may store constructor data without invoking header, cell, data-model or detach callbacks. LambdaColumn bound row functions and interface initialization remain audited; the compiled constructor, null guard and function archives participate in freshness. Source column defaults may store the four reviewed JDK java.base FormatStyle enum constants under type/static-import qualification; source/other enums, enum/formatter methods and locale/time-zone lookups remain unreviewed. SDK FormatStyle and Enum dependencies participate in freshness, and retained diagnostics preserve this storage fact without formatting values. Source providers with no instance state may use reviewed zero-argument SortableDataProvider construction and implicit sort-state allocation. Their iterator/size/model/detach callbacks and page queries stay unevaluated, with unknown rows, models and sort state. Eager calls, initializers, state and unknown constructor effects withhold this expansion; consumer/table construction remains independently audited. Provider protocols and sort-state archives participate in freshness. Existing diagnostics retain that bounded constructor fact and later source blockers; no row/model/sort values or column-generated children are inferred. Exact four-argument DataTable construction has an owned-scope contract when source wrappers preserve framework caption/body/grid and inherited eager methods, with only deferred row/cell factory overrides and constant static storage. Anonymous/source ancestors and interface initialization are checked. Provider queries and header/column/row/cell callbacks remain unevaluated; no private table children or runtime values are inferred. Source wrapper constructors must consist solely of one direct super call forwarding their four parameters in order; extra statements and computed delegation inputs remain unreviewed. Allocation inputs retain their existing effect audit. Other table methods and toolbar/lifecycle effects remain independently unreviewed. Fresh owned DataTable fields/locals can register fresh matching inline AbstractToolbar, HeadersToolbar or AjaxFallbackHeadersToolbar wrappers before attachment or escape. NavigationToolbar construction also audits its eager newPagingNavigator factory: one direct fresh PagingNavigator/AjaxPagingNavigator wrapper forwards ID/table inputs without evaluation. Source navigator-label factories, pager initialization overrides, instance state and eager extra effects stay unreviewed. Paging-link initialization, Ajax/render callbacks, resource/model evaluation and provider data remain unknown; no private navigator IDs are exported. Owned component accessor decoration permits one literal AttributeModifier.replace behavior on the selected pure zero-input getter of a fresh unescaped local owner. The getter returns its own uniquely allocated private-final framework child; source dispatch, constructor paths, interfaces, child uses and constructor effects are audited. Aliases, borrowed/reassigned/attached owners, impure getters, unknown child types and component additions remain unreviewed. Private child IDs, rendering, models, visibility and later state stay unknown. Existing diagnostics retain the accessor fact and exact later blocker without changing selectors or response fields. Fresh inline source component fluent configuration can forward a unary source enum input through private-final source behavior storage into exact private Model storage, returning the same receiver at each link. Selected concrete/anonymous dispatch, source constructors, enum initialization declarations, behavior binding, model identity and field uses are audited. Chains are limited to 12 operations; aliases, computed inputs, custom models, eager extra effects and unknown binding remain unreviewed. Runtime enum initialization outcomes, models, rendering, Ajax callbacks, visibility and later state stay unknown. Existing diagnostics retain completed configuration and later blockers without new private nodes, selectors or response fields. Owned DataTable reference forwarding is reviewed during initial configuration of a fresh unattached source owner: a private-final table has one direct allocation and own attachment, and a final nested direct AbstractToolbar forwards its sole parameter unchanged to the exact compiled constructor. Existing constructor reference snapshots, table construction and interface audits are reused. Borrowed references, aliases, changed dispatch, eager parameter uses and unknown initialization remain unreviewed. Remaining source constructor effects are independently audited. Toolbar IDs, private contents, cache/attachment state, model values, rendering and later callbacks remain unknown. Existing diagnostics retain this fact and the next blocker; no private nodes, parameters, selectors or response fields are added. Owned DataTable columns reads permit the exact final compiled getter during the reviewed toolbar constructor deferred-callback audit. The selected owner input must retain exact JDK List.of provenance, directly or through its unchanged constructor parameter. Internal borrowed-reference tracking permits only exact JDK List.size, local declarations and identical conditional references; mutation, element/iterator/stream queries, escapes, reassignment and uncertain identity remain unreviewed. Custom or borrowed collection implementations receive no size authority. Getter/size bodies and source callbacks are not executed; column count/elements, models, rendering, cache/attachment state and later state remain unknown. Existing diagnostics and fresh native/MCP snapshots share the fact and later blockers without new nodes, selectors or response fields. Source null-guarded owned toolbar caches can assign a reviewed fresh toolbar and perform exact same-table registration under a direct private-field null guard. Shared ownership, constructor and compiled registration checks apply; scoped semantic reference search requires one write and forbids cache aliases/escapes. One later private plain-container cell replacement retains its existing effect audit. Guard predicates, cache presence/reuse, runtime IDs, private contents, models, rendering and later state stay unknown. Semantic traversals skip trivia while retaining cancellation and existing limits. Existing diagnostics carry the completed protocol and later blockers without new nodes, selectors or response fields. Header wrappers only forward constructor inputs, with constant static storage and reviewed deferred render/sort hooks. Navigation wrappers may additionally set a literal output flag on the forwarded table; pager constructors purely forward ID/pageable and an optional label provider. Null or direct constructor parameters supply locators without evaluation. Registration and header construction keep runtime toolbar IDs, private contents, sorting, rendering and provider/model data unknown. Borrowed tables, aliases, extra eager setup and unknown initialization remain unreviewed. Existing diagnostics and archive snapshots retain these facts and later blockers without new response members. Existing diagnostics retain this fact and later blockers, and compiled table/grid dependencies participate in freshness. Equivalent add and queue branches can expose attachmentOrigins. Reviewed ListView item factories and constructor-local scalar guards contribute to the same structure.")
    @McpToolHints(readOnlyHint = McpToolHintValue.TRUE, destructiveHint = McpToolHintValue.FALSE,
        idempotentHint = McpToolHintValue.TRUE, openWorldHint = McpToolHintValue.FALSE)
    suspend fun wicket_get_page_structure(
        @McpDescription("Java qualified source class name, using dots for nested classes. No file paths or library-only targets.") className: String,
        @McpDescription("Exact IntelliJ module name to disambiguate duplicate classes. Default: no module restriction within the selected project.") moduleName: String? = null,
        @McpDescription("Source-set selection: main, test, or any. Default: main. Ambiguous matches are rejected.") sourceSet: String = "main",
        @McpDescription("Also discover bounded SUBMISSION_TEMPLATE ordinary form onSubmit/onError declarations with own-companion paths and unknown initial hierarchy, plus dialog submission sources, declared feedback/Ajax targets and guarded fresh content placements with unknown validation/business/runtime outcomes, plus own/caller/inherited, EVENT_TEMPLATE replacement-site, SELECTION_TEMPLATE registered-step and TREE_TEMPLATE node-relative tree and FORM_TEMPLATE wrapper-relative composite input contexts, including registered custom input constructor provenance, and REPEATER_TEMPLATE conditional item populations using shared analysis. Default false preserves primary report selection. Adds navigationContexts with discoveryComplete, exact binding projections and source dependencies; truncated marks exhausted discovery bounds. Context node IDs are snapshot-local; fetch the named caller's structure again before selection. No complete caller graph or runtime hierarchy is claimed. If the combined response is too large, use wicket_get_navigation_contexts to list and retrieve individual contexts.") includeNavigationContexts: Boolean = false,
    ): String = analyze(WicketMcpReport.STRUCTURE, className, moduleName, sourceSet, includeNavigationContexts = includeNavigationContexts)

    @Suppress("FunctionName")
    @McpTool(title = "Get Wicket navigation contexts")
    @McpDescription("List bounded source navigation contexts without the primary page graph, or retrieve one complete existing context projection by contextId. Omit contextId for an index of snapshot-bound IDs, source locations, relationships and scope/binding counts. Pass an ID from the current target's index to retrieve that context's exact warnings, provenance, scopes, bindings and uncertainty. Every call refreshes the shared native analysis and checks freshness; changed sources, module/source-set/target or project invalidate IDs with STALE_CONTEXT_SELECTION. No persistent server snapshot or runtime IDs are created. Discovery incompleteness remains explicit and truncated reflects discovery bounds, not deliberate context selection. Every response retains the 512-KiB limit; an oversized single context returns RESPONSE_TOO_LARGE without graph truncation. Models, callbacks, runtime presence, visibility and later state remain unknown. Existing structure/validation/component-context contracts are unchanged. CONFIRMATION_TEMPLATE optionally retains submissionTemplate.confirmation source ask/storage/guarded consumer route and data-call declarations. Initiating dispatch, current registration, slot presence, cleanup reachability, mutation outcomes and equality effects stay unknown; callbacks are not evaluated. Optional confirmation.selectionClears adds exact source helper/getter/model-read/Collection.clear/refresh locations with unknown model, column dispatch, mutability and outcomes. No helper or model is executed. Separate ACTION_TEMPLATE contexts describe source constructor BiConsumer arguments with one reviewed private List.replaceAll loop and canonical record enum-component substitution. actionTemplate retains registration, loop, equality, record-transform and component-argument source locations plus shared feedback/Ajax/selection-helper declarations. Registration/storage, UI dispatch, visibility, rows, equality/enum effects and mutation/business outcomes stay unknown. No callback, helper, predicate or record constructor is executed; no runtime trigger ID or form association is reconstructed. Initial attachment declarations can also retain source-proved callback storage on a fresh constructor-local registrar whose complete method only assigns its private callback slot and returns itself. Optional storedActionRegistrations records allocation, registration, method, slot and callback locations. A registrar can have up to 64 standalone or fluent-chained registration links after all of its local uses pass the same storage-only audit and each link returns this; aliases, eager calls or escapes withhold the entire group. Entries sharing allocation and slot locations describe source sites, not concurrently active callbacks. Chain and local-initializer registrationLocation values point to distinct method-name tokens and action contexts reuse those exact locations. A direct new allocation may root a named constructor-local initializer chain; its links and every later local use share the same complete audit and 64-site limit. Bare allocations, aliases, fields and arbitrary factories are not granted local identity. All such attachment bindings are INFERRED with no rename authority; later active registration, dispatch, visibility, tree state and business outcomes remain unknown. Optional evidence includes declared form constraints and conversion links, record add/remove helpers, guarded wizard transitions, and NestedTree child-subtree factories.")
    @McpToolHints(readOnlyHint = McpToolHintValue.TRUE, destructiveHint = McpToolHintValue.FALSE,
        idempotentHint = McpToolHintValue.TRUE, openWorldHint = McpToolHintValue.FALSE)
    suspend fun wicket_get_navigation_contexts(
        @McpDescription("Java qualified source class name, using dots for named member classes.") className: String,
        @McpDescription("Exact module name when className is ambiguous in this project.") moduleName: String? = null,
        @McpDescription("main, test, or any source roots in the selected project.") sourceSet: String = "main",
        @McpDescription("Opaque contextId from this target's current index. Omit to list available contexts; refresh the index after edits or STALE_CONTEXT_SELECTION.") contextId: String? = null,
    ): String = analyze(WicketMcpReport.NAVIGATION, className, moduleName, sourceSet, contextId = contextId)

