        @McpDescription("Qualified Java source WebPage, Panel or FormComponentPanel class. The existing Spring scaffold requires a concrete top-level non-generic subject with Spring intent.") className: String,
        @McpDescription("Exact IntelliJ module name. Default: no module restriction; ambiguous classes are rejected.") moduleName: String? = null,
        @McpDescription("Source-set selection: main, test or any. Default: main.") sourceSet: String = "main",
    ): String = analyze(WicketMcpReport.SPRING_TEST_PLAN, className, moduleName, sourceSet)

    @Suppress("FunctionName")
    @McpTool(title = "Get Wicket test plan")
    @McpDescription("Prepare a WicketTester/JUnit Java scaffold for a concrete top-level non-generic source WebPage, Panel or FormComponentPanel. Recognized Wicket-Spring intent selects the existing Spring recipe. Returns envelope schema 1 and testPlan schema 1 with complete source, constructor strategy, required dependencies, eligible test roots and manual setup. Optional dependencyGraph links detected fields to generated mocks or manual setup. Supply routePath and optionally applicationClass for a mounted page. routeParameters overrides sample values for declared placeholders. Optional-placeholder plans retain a second request omitting them. Reviewed session factories add session assertions; supported Wicket auth-roles applications test anonymous redirection and the real sign-in method using test-account credentials provided to the generated test at runtime. Set mountedResource with the WebApplication class and fixed routePath for resource assertions, optionally supplying expectedContentType and expectedBodySha256. Mounted plans include registration source. Uses host projectPath, default markup, module/source-set selection, external refresh, smart/committed reads, 30-second deadline, freshness check and 512-KiB response bound. Read-only. Test execution, application startup, runtime bindings, credential values, and dependency availability remain outside planning.")
    @McpToolHints(readOnlyHint = McpToolHintValue.TRUE, destructiveHint = McpToolHintValue.FALSE,
        idempotentHint = McpToolHintValue.TRUE, openWorldHint = McpToolHintValue.FALSE)
    suspend fun wicket_get_test_plan(
        @McpDescription("Qualified Java source WebPage, Panel or FormComponentPanel class, or source WebApplication when mountedResource is true. Concrete top-level non-generic subjects only.") className: String,
        @McpDescription("Exact IntelliJ module name. Default: no restriction; duplicate source matches are rejected.") moduleName: String? = null,
        @McpDescription("Source-set selection main, test or any. Default main.") sourceSet: String = "main",
        @McpDescription("Exact declared mounted path pattern from wicket_get_routes. Omit for the isolated test scaffold.") routePath: String? = null,
        @McpDescription("For mounted page tests, the exact qualified source WebApplication class. Required when multiple applications declare the same page route.") applicationClass: String? = null,
        @McpDescription("Generate a fixed resource mount test. Supply the owning WebApplication as className and the exact mount as routePath.") mountedResource: Boolean = false,
        @McpDescription("Optional expected MIME media type such as image/svg+xml, without parameters. Only for mountedResource.") expectedContentType: String? = null,
        @McpDescription("Optional map of declared placeholder names to sample URL-safe path segment values. Only for mounted pages.") routeParameters: Map<String, String>? = null,
        @McpDescription("Optional expected SHA-256 of the response bytes, as 64 hexadecimal characters. Only for mountedResource.") expectedBodySha256: String? = null,
    ): String {
        val view = WicketMcpReport.TEST_PLAN
        if (mountedResource) {
            if (routePath == null || applicationClass != null || routeParameters != null)
                throw McpExpectedError(WicketPageAnalysisRequest.errorJson("INVALID_REQUEST",
                    "For a resource mount, supply the WebApplication as className and its exact routePath. Route parameters are for mounted pages.", view))
            return analyze(view, className, moduleName, sourceSet,
                mountedResourcePath = routePath, expectedContentType = expectedContentType, expectedBodySha256 = expectedBodySha256)
        }
        if (expectedContentType != null || expectedBodySha256 != null)
            throw McpExpectedError(WicketPageAnalysisRequest.errorJson("INVALID_REQUEST", "expectedContentType and expectedBodySha256 require mountedResource.", view))
        if (routePath == null && (applicationClass != null || routeParameters != null))
            throw McpExpectedError(WicketPageAnalysisRequest.errorJson("INVALID_REQUEST", "applicationClass and routeParameters require routePath.", view))
        val mounted = routePath?.let { dev.wicketlens.testing.WicketMountedTestSelection(it, applicationClass, routeParameters.orEmpty()) }
        return analyze(view, className, moduleName, sourceSet, mounted = mounted)
    }

    @Suppress("FunctionName")
    @McpTool(title = "Get Wicket mounted URLs")
    @McpDescription("Discover static mounted path declarations in named WebApplications and anonymous WebApplications directly returned by resolved Spring @Bean methods. Review source init inheritance, closed setup helpers, local mapper initializers, source factories, forwarding subclasses, selected wrappers, package and resource registrations, and reviewed root mapper operations. Bean groups use Configuration#method. Returns envelope schema 1 and routes schema 1 with application-relative paths, optional page/source/HTML locations, registration source, DECLARED/CONDITIONAL/UNRESOLVED status, coverage and possible fixed-path conflicts in notes. Runtime activation, mapper precedence, open dispatch, deferred callbacks and dynamic input values are unknown. Filter by module, application and source set. Uses committed smart reads, cancellation, a 30-second deadline, freshness checks and a 512-KiB response limit. Discovery bounds are 64 applications, 1000 mounts, 512 sources, 20000 steps, 4096 inheritor visits, 12 ancestry levels, 8 active setup methods and 128 setup invocations per application. Read-only. Reinvoke after edits.")
    @McpToolHints(readOnlyHint = McpToolHintValue.TRUE, destructiveHint = McpToolHintValue.FALSE,
        idempotentHint = McpToolHintValue.TRUE, openWorldHint = McpToolHintValue.FALSE)
    suspend fun wicket_get_routes(
        @McpDescription("Optional exact IntelliJ module name; default searches the selected project's Java source modules.") moduleName: String? = null,
        @McpDescription("Optional exact qualified WebApplication class or Configuration#method selector. A bean selector matches all reviewed overloads. Duplicate module declarations stay separately grouped.") applicationClass: String? = null,
        @McpDescription("Source-set selection main, test or any; default main.") sourceSet: String = "main",
    ): String = try {
        dev.wicketlens.routes.WicketRoutesRequest().execute(currentCoroutineContext().project, moduleName, applicationClass, sourceSet)
    } catch (failure: PageAnalysisFailure) {
        throw McpExpectedError(dev.wicketlens.routes.WicketRoutesRequest.errorJson(failure.code, failure.message!!))
    } catch (cancelled: CancellationException) { throw cancelled
    } catch (cancelled: ProcessCanceledException) { throw cancelled
    } catch (hostError: McpExpectedError) { throw hostError
    } catch (failure: Exception) {
        logger<WicketLensMcpToolset>().warn("Wicket mounted URL discovery failed", failure)
        throw McpExpectedError(dev.wicketlens.routes.WicketRoutesRequest.errorJson("ANALYSIS_FAILED", "Route discovery failed. See the IDE log for details."))
    }

    private suspend fun analyze(view: WicketMcpReport, className: String?, moduleName: String?, sourceSet: String,
        componentPath: String? = null, nodeId: String? = null, includeNavigationContexts: Boolean = false, contextId: String? = null,
        mounted: dev.wicketlens.testing.WicketMountedTestSelection? = null,
        mountedResourcePath: String? = null, expectedContentType: String? = null, expectedBodySha256: String? = null): String {
        try {
            val project = currentCoroutineContext().project
            if (mountedResourcePath != null) return WicketPageAnalysisRequest().executeMountedResource(
                project, requireNotNull(className), mountedResourcePath, moduleName, sourceSet, expectedContentType, expectedBodySha256)
            if (className == null && view == WicketMcpReport.DEPENDENCIES)
                return dev.wicketlens.spring.WicketProjectDependencyRequest().execute(project, moduleName, sourceSet)
            return WicketPageAnalysisRequest().execute(project, requireNotNull(className), moduleName, sourceSet, view, componentPath, nodeId, includeNavigationContexts, contextId, mounted)
        } catch (failure: PageAnalysisFailure) {
            throw McpExpectedError(WicketPageAnalysisRequest.errorJson(failure.code, failure.message!!, view))
        } catch (cancelled: CancellationException) { throw cancelled
        } catch (cancelled: ProcessCanceledException) { throw cancelled
        } catch (hostError: McpExpectedError) { throw hostError
        } catch (failure: Exception) {
            logger<WicketLensMcpToolset>().warn("Wicket MCP analysis failed for ${view.tool}", failure)
            throw McpExpectedError(WicketPageAnalysisRequest.errorJson("ANALYSIS_FAILED", "Analysis failed. See the IDE log for details.", view))
        }
    }
